function countZeros(array a, integer n):
    count2 = 0
    count5 = 0
    for i from 0 to n-1:
        while a[i] % 2 == 0:
            a[i] = a[i] / 2
            count2 = count2 + 1
        while a[i] % 5 == 0:
            a[i] = a[i] / 5
            count5 = count5 + 1
    return min(count2, count5)

